corrected_code:
class TenantContextMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        tenant_id = request.headers.get("X-Tenant-ID")
        request.state.tenant_id = int(tenant_id) if tenant_id and tenant_id.isdigit() else None
        return await call_next(request)

app.add_middleware(TenantContextMiddleware)

@app.get("/api/v1/analytics/monthly-revenue")
async def get_monthly_revenue(
    request: Request,
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    requested_tenant = request.state.tenant_id
    if requested_tenant and requested_tenant not in current_user.accessible_tenant_ids:
        raise HTTPException(status_code=403, detail="Unauthorized tenant context")
    tenant_id = requested_tenant or current_user.primary_tenant_id
    stmt = select(RevenueMetric).where(RevenueMetric.tenant_id == tenant_id)
    results = await db.execute(stmt)
    return results.scalars().all()
